      where p.active and not p.duplicate_candidate) <> 18
     or (select count(*) from public.safety_spots where facility_type='aed' and active and not duplicate_candidate) <> 43325
     then raise exception 'Post-insert count mismatch'; end if;
end;
$guard$;
